using System.Text.Json;
using DotaAnalyst.Domain.Abilities;
namespace DotaAnalyst.Tests.Domain;
public class AbilityEffectsV2Tests {
// Relevant components in the twenty CD14 rows; '-' denotes a false positive to exclude.
[Theory]
[InlineData("crystal_maiden_frostbite", "Root,Disarm,DamageOverTime")]
[InlineData("crystal_maiden_crystal_clone", "-Heal")]
[InlineData("lion_impale", "Stun,Nuke")]
[InlineData("shadow_shaman_shackles", "Stun,DamageOverTime,Heal")]
[InlineData("shadow_shaman_mass_serpent_ward", "Summon,-Heal")]
[InlineData("treant_overgrowth", "Root,Disarm,DamageOverTime,-Escape,-Invisibility,-Summon")]
[InlineData("treant_eyes_in_the_forest", "Vision,-Invisibility")]
[InlineData("naga_siren_mirror_image", "Summon,Dispel")]
[InlineData("naga_siren_ensnare", "Root,-Escape")]
[InlineData("naga_siren_song_of_the_siren", "Sleep")]
[InlineData("meepo_earthbind", "Root")]
[InlineData("dark_willow_bramble_maze", "Root,DamageOverTime")]
[InlineData("dark_willow_terrorize", "Fear")]
[InlineData("puck_phase_shift", "Save")]
[InlineData("axe_berserkers_call", "Taunt")]
[InlineData("axe_battle_hunger", "Slow,DamageOverTime")]
[InlineData("legion_commander_press_the_attack", "Heal,Dispel")]
[InlineData("legion_commander_duel", "Taunt")]
[InlineData("bane_enfeeble", "DamageOverTime,-Heal,-Nuke")]
[InlineData("bane_brain_sap", "Heal,Nuke")]
[InlineData("bane_fiends_grip", "Stun,DamageOverTime")]
[InlineData("dazzle_shallow_grave", "Save,-Heal")]
[InlineData("oracle_false_promise", "Save,Dispel,-Heal")]
[InlineData("omniknight_guardian_angel", "Save,-SpellImmunity")]
[InlineData("abaddon_aphotic_shield", "Shield,Dispel,-Summon")]
[InlineData("abaddon_withering_mist", "-Heal")]
[InlineData("antimage_blink", "Escape,-DamageOverTime")]
[InlineData("antimage_mana_break", "-DamageOverTime,-Summon")]
[InlineData("antimage_mana_void", "Stun,Nuke")]
[InlineData("queenofpain_shadow_strike", "Slow,Nuke,DamageOverTime")]
[InlineData("pudge_meat_hook", "ForcedMovement,Nuke,-Stun")]
[InlineData("pudge_rot", "Slow,DamageOverTime,-Nuke")]
[InlineData("pudge_dismember", "Stun,DamageOverTime,Heal,ForcedMovement")]
[InlineData("magnataur_skewer", "ForcedMovement,Escape,Slow,Nuke")]
[InlineData("vengefulspirit_nether_swap", "ForcedMovement,Nuke,Shield,Save")]
public void Cd14RelevantEffects(string key, string expected) {
using var doc=JsonDocument.Parse(Fixtures);
var a=doc.RootElement.EnumerateArray().SelectMany(k=>k.GetProperty("Abilities").EnumerateArray()).First(a=>a.GetProperty("Key").GetString()==key);
var effects=AbilityEffects.Of(Read(a),2);
foreach(var name in expected.Split(',')) { var excluded=name.StartsWith('-'); var effect=Enum.Parse<AbilityEffect>(excluded?name[1..]:name); Assert.True(excluded?!effects.Contains(effect):effects.Contains(effect), key+": "+name); }
}
