[Fact] public void LegacyClassificationMatchesAllTwentyRecordedKits() { using var doc=JsonDocument.Parse(Fixtures); Assert.Equal(20, doc.RootElement.GetArrayLength()); foreach(var kit in doc.RootElement.EnumerateArray()) foreach(var a in kit.GetProperty("Abilities").EnumerateArray()) { var ability=Read(a); var expected=a.GetProperty("Effects").EnumerateArray().Select(e=>Enum.Parse<AbilityEffect>(e.GetString()!)).Order().ToArray(); Assert.Equal(expected, AbilityEffects.Of(ability).Order()); Assert.Equal(expected, AbilityEffects.Of(ability,1).Order()); } }
private static AbilityDetails Read(JsonElement a) => new(a.GetProperty("Key").GetString()!, "fixture", a.GetProperty("Description").GetString(), a.GetProperty("Behavior").EnumerateArray().Select(x=>x.GetString()!).ToArray(), Enum.Parse<AbilityTargetTeam>(a.GetProperty("Team").GetString()!), [], Enum.Parse<AbilityDamageType>(a.GetProperty("Damage").GetString()!), false, Dispellable.Unknown, [], [], a.GetProperty("Headers").EnumerateArray().Select(x=>new AbilityValue(x.GetString()!, x.GetString(), [])).ToArray());
}
